def diag_main(p): return [(r,p[1]-p[0]+r) for r in range(R)]
def diag_anti(p): return [(r,p[0]+p[1]-r) for r in range(R)]
def interior(c): return 0<=c<C
def onborder(r,c): return r in(0,R-1) or c in(0,C-1)
def orient(p,color,pts):
    m=sum(1 for q in pts if q[0]-q[1]==p[0]-p[1]); a=sum(1 for q in pts if q[0]+q[1]==p[0]+p[1])
    return 'a' if a>m else 'm'
