        if interior(c): g[r][c]=6
for p in pts1:
    d=diag_anti(p) if orient(p,1,pts1)=='a' else diag_main(p)
    for r,c in d:
        if interior(c) and not onborder(r,c) and g[r][c]!=6: g[r][c]=1
