pts6=[(4,4),(6,6),(7,14),(15,2)]
def main(p): return [(r,p[1]-p[0]+r) for r in range(R)]
def anti(p): return [(r,p[0]+p[1]-r) for r in range(R)]
def ok(r,c): return 0<=r<R and 0<=c<C
def border(r,c): return r in(0,R-1) or c in(0,C-1)
for r,c in pts1: g[r][c]=1
for r,c in pts6: g[r][c]=6
# paired 1s: fill segment between them on shared diagonal
done=set()
for i,p in enumerate(pts1):
    for q in pts1[i+1:]:
        if q[0]-q[1]==p[0]-p[1]:
            rs=sorted([p[0],q[0]])
            for r in range(rs[0],rs[1]+1):
                c=r-(p[0]-p[1]); g[r][c]=1
            done|={p,q}
        elif q[0]+q[1]==p[0]+p[1]:
            rs=sorted([p[0],q[0]])
            for r in range(rs[0],rs[1]+1):
                c=(p[0]+p[1])-r; g[r][c]=1
            done|={p,q}
# lone 1s: longer interior diagonal, minus border
for p in pts1:
    if p in done: continue
    def cnt(d): return sum(1 for r,c in d if ok(r,c) and not border(r,c))
    d=max([main(p),anti(p)],key=cnt)
    for r,c in d:
        if ok(r,c) and not border(r,c) and g[r][c]!=6: g[r][c]=1
# 6s on a 1-line: perpendicular full diagonal, overwrite
for p in pts6:
    on_main=any(q[0]-q[1]==p[0]-p[1] for q in pts1)
    on_anti=any(q[0]+q[1]==p[0]+p[1] for q in pts1)
    d=anti(p) if on_main else (main(p) if on_anti else [])
    for r,c in d:
        if ok(r,c): g[r][c]=6
